/// Computes the triangular number of n using tail recursion (implemented as a loop)
/// 
/// # Arguments
/// * `n` - Target non-negative integer (must be ≤ 65535 to avoid overflow in u32 result)
/// * `idx` - Current index (must be ≤ n)
/// * `sum` - Mutable accumulator that initially holds triangle(idx) and will be updated to triangle(n)
/// 
/// # Panics
/// May panic on overflow if n > 65535 (since triangle(65535) = 2,147,450,880 > u32::MAX)
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Validate preconditions
    assert!(idx <= n, "idx must be ≤ n");
    
    // The triangular number of n is n*(n+1)/2
    // We need to ensure we don't overflow u32
    // triangle(65535) = 65535*65536/2 = 2,147,450,880 > u32::MAX (4,294,967,295)
    // So n must be ≤ 65535 to fit in u32
    
    // Initialize variables for tail recursion simulation
    let mut current_idx = idx;
    let mut current_sum = *sum;
    
    // Tail-recursive loop: while current_idx < n, add (current_idx+1) to current_sum
    while current_idx < n {
        current_idx += 1;
        // Safe addition since we assume all intermediate values fit in u32
        current_sum = current_sum.wrapping_add(current_idx);
    }
    
    // Update the accumulator with the final result
    *sum = current_sum;
}

/// Helper function to compute triangular number directly
/// triangle(n) = n*(n+1)/2
pub fn triangle_direct(n: u32) -> u32 {
    // Use u64 to avoid overflow during multiplication
    let n64 = n as u64;
    ((n64 * (n64 + 1)) / 2) as u32
}

