    #[test]
    fn test_tail_triangle() {
        // Test case 1: From 0 to 0
        let mut sum = 0; // triangle(0) = 0
        tail_triangle(0, 0, &mut sum);
        assert_eq!(sum, 0);
        
        // Test case 2: From 0 to 5
        let mut sum = 0; // triangle(0) = 0
        tail_triangle(5, 0, &mut sum);
        assert_eq!(sum, 15); // 1+2+3+4+5 = 15
        
        // Test case 3: From 3 to 7
        let mut sum = 6; // triangle(3) = 1+2+3 = 6
        tail_triangle(7, 3, &mut sum);
        assert_eq!(sum, 28); // 1+2+3+4+5+6+7 = 28
        
        // Test case 4: From 5 to 5 (no iteration)
        let mut sum = 15; // triangle(5) = 15
        tail_triangle(5, 5, &mut sum);
        assert_eq!(sum, 15);
        
        // Test case 5: Larger number
        let mut sum = triangle_direct(100);
        tail_triangle(200, 100, &mut sum);
        assert_eq!(sum, triangle_direct(200));
    }
    
    #[test]
